// N2：/T 杀整棵进程树——host 直接子进程只有 guest 插件壳，python/node 的
// worker 都挂在下面；不带 /T 会孤儿化它们（端口/内存泄漏，下次 spawn 撞占）。
let out = std::process::Command::new("taskkill")
    .args(["/PID", &pid.to_string(), "/T", "/F"])
    .output()
    .map_err(|e| format!("taskkill 失败: {e}"))?;
